import { Group, Mesh, PlaneGeometry, Vector3 } from 'three/webgpu';
import { MeshStandardNodeMaterial, vec3, uv, mix, smoothstep, uniform } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  group.position.set(0, 0, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const timelines = [];
  const resources = [];

  // ─────────────────────────────────────────────────────────────────────────
  // 1. BACKDROP PANEL (3.4w × 1.9h, gradient + border)
  // ─────────────────────────────────────────────────────────────────────────
  const panelGeom = new PlaneGeometry(3.4, 1.9, 32, 32);

  const gradientStops = [
    { at: 0.0, hex: '#1a1a22' },
    { at: 1.0, hex: '#111116' }
  ];

  const gradStart = uniform(vec3(
    parseInt(gradientStops[0].hex.slice(1, 3), 16) / 255,
    parseInt(gradientStops[0].hex.slice(3, 5), 16) / 255,
    parseInt(gradientStops[0].hex.slice(5, 7), 16) / 255
  ));
  const gradEnd = uniform(vec3(
    parseInt(gradientStops[1].hex.slice(1, 3), 16) / 255,
    parseInt(gradientStops[1].hex.slice(3, 5), 16) / 255,
    parseInt(gradientStops[1].hex.slice(5, 7), 16) / 255
  ));

  const panelMat = new MeshStandardNodeMaterial({
    colorNode: mix(gradStart, gradEnd, uv().y),
    roughnessValue: 0.6,
    metalnessValue: 0.2,
    clearcoatValue: 0.1
  });

  const panelMesh = new Mesh(panelGeom, panelMat);
  panelMesh.position.z = 0;
  panelMesh.castShadow = true;
  panelMesh.receiveShadow = true;
  group.add(panelMesh);
  resources.push(panelGeom, panelMat);

  // ─────────────────────────────────────────────────────────────────────────
  // 2. QUOTATION MARK (extruded 3D, oversized, red accent)
  // ─────────────────────────────────────────────────────────────────────────
  const quoteMarkText = ctx.fontAtlas.createText('"', {
    fontSize: 62,
    color: '#ff2a38',
    align: 'left'
  });

  quoteMarkText.position.set(-1.35, 0.65, 0.03);
  quoteMarkText.scale.set(1, 1, 1);
  quoteMarkText.userData = quoteMarkText.userData || {};
  group.add(quoteMarkText);

  // ─────────────────────────────────────────────────────────────────────────
  // 3. QUOTE TEXT (floated above panel for raking light edge definition)
  // ─────────────────────────────────────────────────────────────────────────
  const quoteText = ctx.fontAtlas.createText(
    'The bezel action alone is worth the wait. Nothing else on my wrist feels this considered.',
    {
      fontSize: 20,
      color: '#e8ecf2',
      align: 'left',
      maxWidthPx: 400,
      letterSpacingPx: 0
    }
  );

  quoteText.position.set(-1.35, 0.25, 0.03);
  quoteText.scale.set(1, 1, 1);
  group.add(quoteText);

  // ─────────────────────────────────────────────────────────────────────────
  // 4. ATTRIBUTION ROW: rule + name + role
  // ─────────────────────────────────────────────────────────────────────────

  // Accent rule (0.2w × 0.02h, emissive red)
  const ruleGeom = new PlaneGeometry(0.2, 0.02);
  const ruleMat = new MeshStandardNodeMaterial({
    colorNode: vec3(
      parseInt('ff2a38'.slice(0, 2), 16) / 255,
      parseInt('ff2a38'.slice(2, 4), 16) / 255,
      parseInt('ff2a38'.slice(4, 6), 16) / 255
    ),
    emissiveIntensity: 1.4,
    roughnessValue: 0.5,
    metalnessValue: 0
  });
  const ruleMesh = new Mesh(ruleGeom, ruleMat);
  ruleMesh.position.set(-1.35, -0.4, 0.03);
  group.add(ruleMesh);
  resources.push(ruleGeom, ruleMat);

  // Attribution name
  const nameText = ctx.fontAtlas.createText('M. OKAFOR', {
    fontSize: 13,
    color: '#e8ecf2',
    align: 'left',
    letterSpacingPx: 1.04
  });
  nameText.position.set(-1.1, -0.4, 0.03);
  group.add(nameText);

  // Caption / role
  const captionText = ctx.fontAtlas.createText('COLLECTOR SINCE 2019', {
    fontSize: 9,
    color: '#e8ecf2',
    align: 'left',
    letterSpacingPx: 1.08
  });
  captionText.position.set(-1.1, -0.52, 0.03);
  group.add(captionText);

  // ─────────────────────────────────────────────────────────────────────────
  // 5. ENTRANCE ANIMATION
  // ─────────────────────────────────────────────────────────────────────────

  // Panel: fade-up (opacity 0→1 + y +0.2→0)
  panelMesh.material.opacity = 0;
  panelMesh.material.transparent = true;
  const panelTl = gsap.timeline({ paused: true });
  panelTl.fromTo(
    panelMesh.material,
    { opacity: 0 },
    { opacity: 1, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
    0
  );
  panelTl.fromTo(
    panelMesh.position,
    { y: 0.2 },
    { y: 0, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
    0
  );
  timelines.push(panelTl);

  // Quote mark: weighted-settle (scale 1.04→1.0, 900ms)
  quoteMarkText.scale.set(1.04, 1.04, 1.04);
  const markTl = gsap.timeline({ paused: true });
  markTl.to(
    quoteMarkText.scale,
    { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'cubic-bezier(0.165,0.84,0.44,1)' },
    0
  );
  timelines.push(markTl);

  // Fire entrance on creation
  panelTl.play();
  markTl.play();

  // ─────────────────────────────────────────────────────────────────────────
  // 6. CLEANUP
  // ─────────────────────────────────────────────────────────────────────────
  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    resources.forEach((res) => res.dispose?.());
    [panelMesh, quoteMarkText, quoteText, ruleMesh, nameText, captionText].forEach((obj) => {
      if (obj.geometry) obj.geometry.dispose?.();
      if (obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => m.dispose?.());
        } else {
          obj.material.dispose?.();
        }
      }
    });
  };

  return group;
}
